def _student_notice(text: Any) -> str:
    notice = str(text or "").strip()
    lowered = notice.lower()
    if (
        not notice
        or "traceback" in lowered
        or lowered.startswith("ошибка")
        or "не удалось сгенерировать" in lowered
    ):
