) -> None:
    """Сохраняет понятия урока в профиль."""
    if not lesson_full_id or lesson_full_id.endswith(":") or "::" in lesson_full_id:
        return
    cleaned: list[dict[str, str]] = []
    for item in concepts or []:
        if not isinstance(item, dict):
            continue
